/**
 * Lean 4 proofs of the AGL(7,2) structural layer.
 *
 * generateLean4Source() writes a self-contained Lean 4 file for a matrix L
 * and displacement k. It states only facts that hold for that matrix (they
 * are computed here first), and closes every theorem with `decide`, which
 * the Lean kernel checks. No `native_decide`, no `sorry`, no Mathlib: the
 * file builds with the bare Lean toolchain pinned in lean-toolchain.
 *
 * The generated file is a claim until Lean accepts it. For the canonical
 * matrix it is byte-identical to agl72_proof.lean, which CI builds; CI
 * also fails if the two drift apart. For any other matrix, run
 * `lean agl72_proof.lean` on the export before relying on it.
 */

import { BitMatrix7, LeanProofGoal } from '../types/crypto';
import { invertMat7, mulVec7, popcount7 } from './algebra';

const leanList = (rows: readonly (number | string)[]) => `[${rows.join(', ')}]`;

const hex2 = (x: number) => `0x${x.toString(16).padStart(2, '0')}`;

export function generateLean4Source(M: BitMatrix7, k = 0x01): string {
  const { isInvertible, inverse, rank } = invertMat7(M);

  let branch = Infinity;
  let witness = 0;
  for (let b = 1; b < 128; b++) {
    const s = popcount7(b) + popcount7(mulVec7(M, b));
    if (s < branch) {
      branch = s;
      witness = b;
    }
  }

  let fixedPoint = -1;
  for (let b = 0; b < 128 && fixedPoint < 0; b++) {
    if ((mulVec7(M, b) ^ k) === b) fixedPoint = b;
  }

  let kernelWitness = -1;
  for (let b = 1; b < 128 && kernelWitness < 0; b++) {
    if (mulVec7(M, b) === 0) kernelWitness = b;
  }

  const inverseBlock = isInvertible && inverse
    ? `/-- Rows of L⁻¹, computed by Gaussian elimination over F₂. -/
def rowsLinv : List Nat := ${leanList(inverse)}

def Linv (b : Nat) : Nat := mulVec rowsLinv b

/-- L⁻¹ is a two-sided inverse of L on F₂⁷, so L ∈ GL(7,2). -/
theorem Linv_L : ∀ b, b < 128 → Linv (L b) = b := by decide
theorem L_Linv : ∀ b, b < 128 → L (Linv b) = b := by decide
`
    : `/-- L is singular (rank ${rank}): b = ${kernelWitness} is a nonzero vector it sends to 0,
so L ∉ GL(7,2) and f is not a permutation. -/
theorem L_singular : L ${kernelWitness} = 0 := by decide
`;

  const fixedBlock = fixedPoint < 0
    ? `/-- f has no fixed points on F₂⁷. -/
theorem f_no_fixed_points : ∀ b, b < 128 → f b ≠ b := by decide
`
    : `/-- f has a fixed point: f(${fixedPoint}) = ${fixedPoint}. -/
theorem f_fixed_point : f ${fixedPoint} = ${fixedPoint} := by decide
`;

  return `/-
AGL(7,2) structural layer: kernel-checked facts about L and f(b) = L·b ⊕ k,
for L with rows ${leanList(M.map(hex2))} and k = ${hex2(k)}.

Representation. A vector b ∈ F₂⁷ is a natural number below 128 whose bit j
is b_j. Row i of a matrix is a 7-bit mask whose bit j is the entry (i, j).
Row i of L·b is the parity of (row i AND b): the F₂ dot product of that
row with b.

Every theorem is closed by \`decide\`, which the Lean kernel checks. No
\`native_decide\`, no \`sorry\`, no Mathlib: \`lean agl72_proof.lean\` with the
toolchain in lean-toolchain checks the whole file.

Generated by g2the7 (src/math/lean4Proofs.ts). Do not edit by hand.
-/

namespace AGL72

-- \`decide\` unfolds all 128 cases; the default recursion limit is too low.
set_option maxRecDepth 20000

/-- Rows of L. -/
def rowsL : List Nat := ${leanList(M)}

/-- The displacement k. -/
def k : Nat := ${k}

/-- Number of set bits among bits 0..6. -/
def wt (n : Nat) : Nat :=
  (List.range 7).foldl (fun acc j => acc + (n >>> j) % 2) 0

/-- Matrix–vector product over F₂, rows given as masks. -/
def mulVec (rows : List Nat) (b : Nat) : Nat :=
  (List.range 7).foldl
    (fun acc i => acc ||| ((wt (rows.getD i 0 &&& b) % 2) <<< i)) 0

def L (b : Nat) : Nat := mulVec rowsL b

/-- The affine map f(b) = L·b ⊕ k. -/
def f (b : Nat) : Nat := L b ^^^ k

/-- L maps F₂⁷ into F₂⁷. -/
theorem L_closed : ∀ b, b < 128 → L b < 128 := by decide

${inverseBlock}
/-- Branch number at least ${branch}: wt(b) + wt(L·b) ≥ ${branch} for every nonzero b. -/
theorem branch_number_ge : ∀ b, b < 128 → b ≠ 0 → ${branch} ≤ wt b + wt (L b) := by
  decide

/-- The bound is attained at b = ${witness}, so the branch number is exactly ${branch}. -/
theorem branch_number_exact : wt ${witness} + wt (L ${witness}) = ${branch} := by decide

${fixedBlock}
end AGL72
`;
}

const DECIDE_EXPLANATION =
  '`decide` evaluates the statement for every b < 128 and the Lean kernel checks the evaluation. ' +
  'It uses no axiom beyond `propext` and does not trust compiled code, unlike `native_decide`.';

